/**
 * PIXEL CREW — Zod Input/Output Schema Generator
 * 
 * Generates runtime Zod validation schemas for request bodies, query parameters,
 * and response models. Enforces strict input stripping and type safety.
 */

export class SchemaGenerator {
  /**
   * Generate Zod schemas for an entity
   * @param {object} entity 
   * @returns {string} TypeScript Zod schema file content
   */
  static generateZodSchema(entity) {
    const name = entity.name;
    const fields = entity.fields || [];

    let code = `import { z } from "zod";

/**
 * Domain Schema for ${name}
 * Auto-generated by Pixel Crew Backend Synthesizer
 */

export const ${name}Schema = z.object({\n`;

    fields.forEach(f => {
      let zodType = 'z.string()';
      if (f.type === 'number') zodType = 'z.number()';
      else if (f.type === 'boolean') zodType = 'z.boolean()';
      else if (f.type === 'datetime') zodType = 'z.string().datetime()';
      else if (f.type === 'json') zodType = 'z.record(z.any())';

      if (!f.required) {
        zodType += '.optional()';
      }

      code += `  ${f.name}: ${zodType},\n`;
    });

    code += `});

export const Create${name}Schema = ${name}Schema.omit({\n  id: true,\n  createdAt: true,\n  updatedAt: true\n});

export const Update${name}Schema = Create${name}Schema.partial();

export const ${name}QuerySchema = z.object({
  page: z.coerce.number().min(1).default(1),
  limit: z.coerce.number().min(1).max(100).default(20),
  cursor: z.string().optional(),
  search: z.string().optional(),
  sortBy: z.string().default("createdAt"),
  sortOrder: z.enum(["asc", "desc"]).default("desc")
});

export type ${name}DTO = z.infer<typeof ${name}Schema>;
export type Create${name}DTO = z.infer<typeof Create${name}Schema>;
export type Update${name}DTO = z.infer<typeof Update${name}Schema>;
export type ${name}QueryDTO = z.infer<typeof ${name}QuerySchema>;
`;

    return code;
  }
}
